import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl with sinusoidal modulation and pairwise interactions.

    Formula: f(x) =  (quadratic_bowl(x) * (1 + modulation(x))) + interactions(x) + skew(x)
    """

    def quadratic_bowl(x):
        return np.sum(x**2)

    def modulation(x):
         return 0.1 * np.sin(5 * x[0] + x[1])

    def interactions(x):
        return 0.05 * x[0] * x[1]


    def skew(x):
        return 0.5 * np.maximum(0, x[0] + x[1])**3


    return (quadratic_bowl(x) * (1 + modulation(x))) + interactions(x) + skew(x)
